"""Offline worker/coordinator pipeline: certified sharing replay.

``run_case`` replays one case of PROTOCOL.md.  It owns the transport registry
(immutable proposals, receipt history, checkpoints), the generation counter, the
cached partial barrier and the consensus controller, and answers every event
with its exact schema.
"""
from __future__ import annotations

import numpy as np

from te.algorithms.communication.partial_barrier import PartialBarrier
from te.algorithms.formulations.path_based.distributed.coordinator import Coordinator
from te.algorithms.formulations.path_based.distributed.worker import DenseSolver
from te.path_providers.base import PathProvider


def num(value):
    """Finite JSON float, with negative zero normalised."""
    out = float(value) + 0.0
    if out != out or out in (float('inf'), float('-inf')):
        raise ValueError('non finite response value')
    return out


def nums(values):
    return [num(v) for v in values]


class Replay:
    """Replay state of a single case."""

    def __init__(self, case):
        self.edges = case['edges']
        self.E = len(self.edges)
        self.c = np.array([float(e[2]) for e in self.edges], dtype=float)
        coms = case['commodities']
        self.commodities = coms
        self.K = len(coms)
        self.slot_count = [len(c['paths']) for c in coms]
        self.paths = [list(c['paths']) for c in coms]
        self.demand = np.array([float(c['demand']) for c in coms], dtype=float)
        self.workers = [list(w) for w in case['workers']]
        self.W = len(self.workers)
        self.quorum = int(case['quorum'])
        self.max_lag = int(case['max_lag'])
        a, b = case['relax']
        self.alpha = a / b
        self.mode = case['mode']
        self.rho = int(case['rho'])
        self.generation = 0
        self.cache_flow = [[0.0] * self.slot_count[k] for k in range(self.K)]
        self.tickets = {}
        self.sequence = {}
        self.delivered = set()
        self.checkpoints = {}
        self.issued = 0
        self._fresh_state()

    # ------------------------------------------------------------------ state
    def _fresh_state(self):
        """Initial/generation-reset algorithm, cache and barrier state."""
        self.cache_flow = [[0.0] * self.slot_count[k] for k in range(self.K)]
        self.barrier = PartialBarrier(self.W, self.quorum, self.max_lag, self.E)
        self.coordinator = Coordinator(self.E, self.rho, self.alpha, workers=self.W)
        self.coordinator.set_live(self.c > 0)

    # ------------------------------------------------------------- controller
    def _cache_loads(self):
        """Raw per-worker loads, their total and the normalized utilization."""
        storage = self.barrier.storage
        total = storage.sum(axis=0) if self.W else np.zeros(self.E)
        util = np.zeros(self.E)
        live = self.c > 0
        if live.any():
            util[live] = total[live] / self.c[live]
        return storage, total, util

    def worker_bias(self, w):
        """Normalized signed bias of one worker from the current cache."""
        storage, _total, util = self._cache_loads()
        own = np.zeros(self.E)
        live = self.c > 0
        if live.any():
            own[live] = storage[w][live] / self.c[live]
        self.coordinator.set_live(live)
        self.coordinator.record_cache(util)
        return self.coordinator.bias(own)

    # ----------------------------------------------------------------- events
    def dispatch(self, ev):
        op = ev['op']
        if op == 'configure':
            return self.do_configure(ev)
        if op == 'issue':
            return self.do_issue(ev)
        if op == 'deliver':
            return self.do_deliver(ev)
        if op == 'step':
            return self.do_step(ev)
        if op == 'retune':
            return self.do_retune(ev)
        if op == 'save':
            return self.do_save(ev)
        if op == 'restore':
            return self.do_restore(ev)
        if op == 'audit':
            return self.do_audit(ev)
        raise ValueError('unsupported event')

    def do_configure(self, ev):
        for i, val in ev['capacity']:
            self.c[int(i)] = float(val)
        for i, val in ev['demand']:
            self.demand[int(i)] = float(val)
        for k, p, path in ev['paths']:
            self.paths[int(k)][int(p)] = path
        self.mode = ev['mode']
        self._fresh_state()
        self.generation += 1
        return {'op': 'configure', 'generation': self.generation}

    def do_issue(self, ev):
        ticket = int(ev['id'])
        w = int(ev['worker'])
        seq = self.issued
        self.issued += 1
        bias = self.worker_bias(w)
        owned = list(self.workers[w])
        provider = PathProvider([self.paths[k] for k in owned], self.E)
        solver = DenseSolver(provider, gids=owned)
        solver.configure(self.c, [float(self.demand[k]) for k in owned],
                         None, bias, self.mode, self.rho, gids=owned)
        result = solver.solve()
        record = {'ticket': ticket, 'seq': seq, 'worker': w,
                  'generation': self.generation, 'owned': owned, 'result': result}
        self.tickets[ticket] = record
        self.sequence[ticket] = seq
        return {'op': 'issue', 'id': ticket, 'worker': w,
                'generation': self.generation, 'bias': nums(bias),
                'rho': self.rho, 'result': result}

    def do_deliver(self, ev):
        ticket = int(ev['id'])
        record = self.tickets[ticket]
        if ticket in self.delivered:
            status = 'duplicate'
        else:
            self.delivered.add(ticket)
            if record['generation'] != self.generation:
                status = 'obsolete'
            else:
                seq = self.sequence[record['ticket']]
                latest = self.barrier.last_accepted[record['worker']]
                if latest is not None and latest > seq:
                    status = 'superseded'
                elif record['result']['status'] == 'infeasible':
                    status = 'infeasible'
                else:
                    status = 'accepted'
                    self.accept(record)
        return {'op': 'deliver', 'id': ticket, 'status': status}

    def accept(self, record):
        """Only acceptance changes the cache."""
        w = record['worker']
        flow = record['result']['flow']
        for i, k in enumerate(record['owned']):
            self.cache_flow[k] = [float(v) for v in flow[i]]
        loads = record['result']['edge_load']
        self.barrier.arrive(w, loads)
        self.barrier.accept_sequence(w, self.sequence[record['ticket']])

    def do_step(self, ev):
        if not self.barrier.can_advance():
            missing, stale = self.barrier.blockers()
            return {'op': 'step', 'status': 'waiting', 'missing': missing,
                    'stale': stale, 'fresh': sorted(self.barrier.arrivals)}
        live = self.c > 0
        _storage, total, util = self._cache_loads()
        out = self.coordinator.step(util, live, self.mode)
        self.barrier.advance()
        return {'op': 'step', 'status': 'advanced', 'round': self.barrier.clock,
                'load': nums(total), 'ceiling': num(out['ceiling']),
                'z': nums(out['z']), 'dual': nums(out['dual']),
                'pressure': nums(out['pressure'])}

    def do_retune(self, ev):
        self.rho = int(ev['rho'])
        self.coordinator.retune(self.rho)
        return {'op': 'retune', 'rho': self.rho}

    def do_save(self, ev):
        self.checkpoints[ev['name']] = self.snapshot()
        return {'op': 'save', 'name': ev['name']}

    def do_restore(self, ev):
        self.restore(self.checkpoints[ev['name']])
        self.generation += 1
        return {'op': 'restore', 'name': ev['name'], 'generation': self.generation}

    def do_audit(self, ev):
        storage, total, _util = self._cache_loads()
        seen = self.barrier.seen
        return {'op': 'audit', 'generation': self.generation,
                'round': self.barrier.clock, 'rho': self.rho,
                'flow': [[num(v) for v in row] for row in self.cache_flow],
                'worker_load': [[num(v) for v in storage[w]] for w in range(self.W)],
                'load': nums(total),
                'z': nums(self.coordinator.Z), 'dual': nums(self.coordinator.dual),
                'seen': sorted(seen), 'fresh': sorted(self.barrier.arrivals),
                'age': self.barrier.ages()}

    # ------------------------------------------------------------- checkpoints
    def snapshot(self):
        return {'c': np.array(self.c, dtype=float, copy=True),
                'demand': np.array(self.demand, dtype=float, copy=True),
                'paths': [list(row) for row in self.paths],
                'mode': self.mode,
                'rho': self.rho,
                'flow': [list(row) for row in self.cache_flow],
                'barrier': self.barrier.snapshot(),
                'coordinator': self.coordinator.snapshot()}

    def restore(self, state):
        self.c = np.array(state['c'], dtype=float, copy=True)
        self.demand = np.array(state['demand'], dtype=float, copy=True)
        self.paths = [list(row) for row in state['paths']]
        self.mode = state['mode']
        self.rho = state['rho']
        self.cache_flow = [list(row) for row in state['flow']]
        self.barrier = PartialBarrier(self.W, self.quorum, self.max_lag, self.E)
        self.barrier.restore(state['barrier'])
        self.coordinator = Coordinator(self.E, self.rho, self.alpha, workers=self.W)
        self.coordinator.restore(state['coordinator'])
        self.coordinator.set_live(self.c > 0)


def run_case(case):
    replay = Replay(case)
    return {'events': [replay.dispatch(ev) for ev in case['events']]}
